    }
  })

  // ---------- El panel acoplado: si lo cierra la persona, Emi vuelve a la banda y se queda ahí ----------

  on('ui.close', async ($, e, next) => {
    if (e.id === PANEL) {
      await update($, panel, () => false).catch(() => undefined)
      await ajustarRapido($)
