              <Text key={linea} dimColor wrap="truncate-end">
                {linea}
              </Text>
            ))}
            <Button key="emi-compacta" label="compacta" onPress={() => update($, ajustes, x => ({ ...x, tamano: 'compacta' as const }))} />
          </Box>
        </Box>
      )
      return ajeno ? (
        <Box flexDirection="column">
          {banda}
          {ajeno}
        </Box>
      ) : (
        banda
