    )
    return ajeno ? (
      <Box flexDirection="column">
        {banda}
        {ajeno}
      </Box>
    ) : (
      banda
    )
  })

  // ---------- El panel de Emi: el mayor sprite que cabe en el hueco real del panel ----------

  on('ui.render', { component: 'Pane', requestId: PANEL }, async ($, e) => {
