          <Text color={color} bold wrap="truncate-end">
            {dicho}
          </Text>
          <Text dimColor wrap="truncate-end">
            {extra || ' '}
          </Text>
          <Button key="emi-volver" label="volver a la banda" onPress={volver} />
        </Box>
      )
      return especial || plan.texto === 'abajo' ? (
        <Box flexDirection="column">
